 Make sure your API invocation call has a header: 'Authorization : Bearer ACCESS_TOKEN' or 'Authorization : Basic ACCESS_TOKEN' or 'apikey: API_KEY'","type":"string"},"message":{"example":"Unauthorized","type":"string"}},"type":"object"}}},"description":"Unauthorized"},"403":{"content":{"text/plain":{"schema":{"example":"Access Denied","type":"string"}}},"description":"Forbidden"},"404":{"description":"server cannot find the requested resource"},"500":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"900900 - Unclassified Authentication Failure. May be returned either bare or with a trailing ": " separator; match on the code itself and tolerate the separator.","example":"900900","pattern":"^(ABDM-\d{4}|\d{3,6})(: )?$","type":"string"},"description":{"example":"Access failure for API: /hiecm/api/v3, version: v3 status: (900900) - Unclassified Authentication Failure","type":"string"},"message":{"example":"Unclassified Authentication Failure","type":"string"}},"type":"object"}}},"description":"Internal Server Error"},"503":{"content":{"application/json":{"schema":{"properties":{"code":{"description":"ABDM-1024 - Dependent service unavailable. May be returned either bare (`ABDM-1024`) or with a trailing ": " separator (`ABDM-1024: `); match on the code itself and tolerate the separator.","example":"ABDM-1024","pattern":"^(ABDM-\d{4}|\d{3,6})(: )?$","type":"string"},"message":{"example":"Dependent service unavailable","type":"string"}},"required":["code","message"],"type":"object"}}},"description":"Service Unavailable"}},"security":[{"bearerAuth":[]}],"summary":"API used to generate link token to link the health records","tags":["abdm-link-token-hip"],"x-abdm-nha-operation-id":"abdm-link-token 1"}}
